<script>
// O PHP monta a página; o JavaScript atualiza o carrinho sem recarregar.
const products = <?= json_encode(array_map(static function (array $p): array { return ['id' => $p['id'], 'nome' => $p['nome'], 'preco' => $p['preco']]; }, $produtos), JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_UNICODE) ?>;
const whatsapp = <?= json_encode($whatsapp, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>;
const cart = new Map();
const money = value => new Intl.NumberFormat('pt-BR', {style:'currency',currency:'BRL'}).format(value);
const nameInput = document.getElementById('nome');
const addressInput = document.getElementById('endereco');
const paymentInput = document.getElementById('pagamento');
const selected = () => products.filter(p => (cart.get(p.id) || 0) > 0);
const total = () => selected().reduce((sum,p) => sum + p.preco * cart.get(p.id),0);
function refresh() {
  const container = document.getElementById('cart');
  container.replaceChildren();
  const items = selected();
  if (!items.length) {
    const empty = document.createElement('p'); empty.className='empty'; empty.textContent='Seu carrinho está vazio. Escolha um docinho ao lado 💕'; container.append(empty);
  } else {
    const list = document.createElement('ul'); list.className='cart-list';
    items.forEach(p => {
      const row=document.createElement('li'), label=document.createElement('span'), price=document.createElement('span');
      label.textContent=`${cart.get(p.id)}x ${p.nome}`; price.textContent=money(p.preco*cart.get(p.id)); price.className='line-price'; row.append(label,price); list.append(row);
    }); container.append(list);
  }
  products.forEach(p => document.getElementById(`quantity-${p.id}`).textContent=cart.get(p.id)||0);
  document.getElementById('total').textContent=money(total());
  document.getElementById('send').disabled=!items.length || !nameInput.value.trim();
}
document.querySelectorAll('[data-change]').forEach(button => button.addEventListener('click', () => {
  const id=Number(button.dataset.id), quantity=Math.max(0,(cart.get(id)||0)+Number(button.dataset.change));
  if(quantity) cart.set(id,quantity); else cart.delete(id);
  refresh();
}));
nameInput.addEventListener('input',refresh);
document.getElementById('order-form').addEventListener('submit', event => {
  event.preventDefault();
  if(!selected().length || !nameInput.value.trim()) return;
  const lines=selected().map(p => `• ${cart.get(p.id)}x ${p.nome} — ${money(p.preco*cart.get(p.id))}`);
  const message=`Olá, Lili! Quero fazer um pedido 💕\n\n${lines.join('\n')}\n\n*Total: ${money(total())}*\n\nForma de pagamento: ${paymentInput.value}\nNome: ${nameInput.value.trim()}\nEndereço: ${addressInput.value.trim()}`;
  window.open(`https://wa.me/${whatsapp}?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');
});
</script>
